#!/usr/bin/env node
import fs from 'node:fs';
import path from 'node:path';
import { execFileSync } from 'node:child_process';
import { fileURLToPath, pathToFileURL } from 'node:url';
import {
  assertOwnedOutput, captureSource, cleanBuildEnvironment, compilerLockSubset, confinedPath, copyInventoriedFile,
  createOwnedOutput, demand, fileIdentity, findExternalExecutable, inventoryTree, makeReadOnly,
  readSourceIdentity, regularRoot, runBuildCommand, seedLockedPublicCache, verifyDependencyTree, writeJson, writeNew
} from './native-build-files.mjs';
import { downloadPinnedFile, inspectNativeMachine, pinnedRuntime, preparePrivateRuntime, runtimeDefinition } from './node-runtime.mjs';
import { canonicalJson, inspectArchiveDocumentation, inspectFile, sha256, verifyPackagedDocumentation } from '../release-evidence.mjs';
import { validateWorkflowPolicy } from '../release-evidence-github.mjs';

export const nativeEntrypoints = (target) => ({
  launcher: target.startsWith('win32-') ? 'bin/liftoff.exe' : 'bin/liftoff',
  runtime: target.startsWith('win32-') ? 'runtime/node.exe' : 'runtime/node',
  cli: 'dist/cli.js'
});

export const nativePlanSmokeCases = [
  ['plan', '--project', 'native-smoke-node', '--no-genai', '--api', 'node', '--cloud', 'azure',
    '--region', 'eastus', '--spec', 'openspec', '--agents', 'copilot', '--governance', 'single-maintainer-gitflow', '--no-frontend'],
  ['plan', '--project', 'native-smoke-rag', '--genai', '--pattern', 'rag', '--cloud', 'azure',
    '--region', 'eastus', '--spec', 'openspec', '--agents', 'copilot', '--governance', 'single-maintainer-gitflow', '--no-frontend']
];

export const packagedGenerationSmoke = `
import fs from 'node:fs/promises';
import path from 'node:path';
import { createHash } from 'node:crypto';
const base = new URL(process.argv[1]);
const [planning, generation, staging, reader, resources] = await Promise.all([
  import(new URL('dist/application/project/planning.js', base)),
  import(new URL('dist/templates.js', base)),
  import(new URL('dist/init-filesystem.js', base)),
  import(new URL('dist/application/project/manifest.js', base)),
  import(new URL('dist/adapters/packaged-assets/resource-catalog.js', base))
]);
const cases = [
  { id: 'node-fastify', projectName: 'native-generated-node', genai: false, apiStack: 'node' },
  { id: 'genai-rag', projectName: 'native-generated-rag', genai: true, pattern: 'rag' }
];
const results = [];
for (const entry of cases) {
  const { id, ...selection } = entry;
  const installed = resources.currentStandardsManifestContext();
  const plan = planning.buildProjectPlan({ ...selection, cloud: 'azure', region: 'eastus',
    specWorkflow: 'openspec', agents: ['copilot'], governanceProfile: 'single-maintainer-gitflow',
    includeFrontend: false }, { requireProjectName: true });
  const artifacts = generation.buildArtifacts(plan);
  if (!artifacts.length || !artifacts.some(a => a.logicalName === 'manifest') ||
      !artifacts.some(a => a.pathParts[0] === 'backend')) throw Error('Required generated artifacts are missing');
  await staging.withStagingArea(async area => {
    await staging.writeStagedArtifacts(area, artifacts, 'liftoff');
    const files = await staging.validateStagedTree(area);
    if (files.length !== artifacts.length) throw Error('Actual staged generation inventory differs');
    for (const artifact of artifacts) {
      const bytes = await fs.readFile(path.join(area.root, ...artifact.pathParts));
      if (!bytes.equals(Buffer.from(artifact.content, 'utf8'))) throw Error('Generated bytes changed during staged write');
    }
    const manifest = await reader.loadManifest(area.root);
    if (manifest.artifactVersion !== 8 || manifest.provenance.kind !== 'generated') throw Error('Generated manifest readback failed');
    results.push({ id, operation: 'packaged-render-stage-readback', files: files.length,
      buildInfoKind: installed.buildInfo.kind, templateCatalogDigest: installed.resourceCatalogDigest,
      profilesDigest: installed.profiles.digest,
      manifestSha256: createHash('sha256').update(await fs.readFile(path.join(area.root, 'liftoff.manifest.json'))).digest('hex') });
  });
}
console.log(JSON.stringify({ kind: 'packaged-generation-source-smoke', initializedProject: false,
  frameworkExecuted: false, dependenciesInstalled: false, providerExecuted: false, results }));
`;

export function nativeBuildInfoDocument({
  version, sourceCommit, target, nodeVersion, resourcesDigest, profilesDigest, builtAt
}) {
  const definition = runtimeDefinition(target);
  const [os, arch] = definition.target.split('-');
  return {
    schemaVersion: 1, kind: 'native-release', product: 'liftoff', version, commit: sourceCommit,
    target: { os, arch, platform: target }, runtime: { name: 'node', version: nodeVersion },
    resourcesDigest, profilesDigest, buildDate: builtAt
  };
}

export function posixLauncher() {
  return `#!/bin/sh
set -eu
unset NODE_OPTIONS NODE_PATH NODE_EXTRA_CA_CERTS NODE_ICU_DATA NODE_V8_COVERAGE NODE_REPL_EXTERNAL_MODULE NODE_TLS_REJECT_UNAUTHORIZED
unset OPENSSL_CONF OPENSSL_MODULES OPENSSL_ENGINES BASH_ENV ENV LD_PRELOAD LD_LIBRARY_PATH DYLD_INSERT_LIBRARIES DYLD_LIBRARY_PATH DYLD_FRAMEWORK_PATH
SOURCE=$0
case "$SOURCE" in /*) ;; *) SOURCE="$PWD/$SOURCE" ;; esac
COUNT=0
while [ -L "$SOURCE" ]; do
  COUNT=$((COUNT + 1))
  if [ "$COUNT" -gt 32 ]; then printf '%s\\n' 'Liftoff launcher: symbolic-link chain is too deep' >&2; exit 126; fi
  LINK=$(/usr/bin/readlink "$SOURCE") || exit 126
  case "$LINK" in /*) SOURCE="$LINK" ;; *) SOURCE="\${SOURCE%/*}/$LINK" ;; esac
done
ROOT=$(CDPATH= cd -P "\${SOURCE%/*}/.." && pwd -P) || exit 126
if [ ! -f "$ROOT/runtime/node" ] || [ -L "$ROOT/runtime/node" ] || [ ! -x "$ROOT/runtime/node" ] || [ ! -f "$ROOT/dist/cli.js" ] || [ -L "$ROOT/dist/cli.js" ]; then
  printf '%s\\n' 'Liftoff launcher: required private runtime or CLI is missing, linked, or not executable' >&2
  exit 126
fi
exec "$ROOT/runtime/node" "$ROOT/dist/cli.js" "$@"
`;
}

function npmCliIdentity(projectRoot, selected) {
  let cli = selected;
  if (!cli) {
    for (const directory of (process.env.PATH ?? '').split(path.delimiter)) {
      if (!path.isAbsolute(directory)) continue;
      const launcher = path.join(directory, process.platform === 'win32' ? 'npm.cmd' : 'npm');
      if (!fs.existsSync(launcher)) continue;
      const resolved = fs.realpathSync(launcher);
      if (path.basename(resolved) === 'npm-cli.js') { cli = resolved; break; }
    }
  }
  demand(typeof cli === 'string' && path.isAbsolute(cli), 'Provide an explicitly verified existing npm-cli.js via --npm-cli when npm is not an installed symlink launcher');
  cli = fs.realpathSync(cli);
  demand(path.basename(cli) === 'npm-cli.js' && path.basename(path.dirname(cli)) === 'bin' &&
    path.basename(path.dirname(path.dirname(cli))) === 'npm', 'Build npm must be its actual installed npm-cli.js, not an arbitrary shim');
  const relative = path.relative(projectRoot, cli);
  demand(relative.startsWith('..') || path.isAbsolute(relative), 'Build npm may not come from project/staging-controlled scope');
  const packageFile = path.join(path.dirname(path.dirname(cli)), 'package.json');
  const metadata = JSON.parse(fs.readFileSync(packageFile, 'utf8'));
  demand(metadata.name === 'npm' && /^12\.\d+\.\d+$/.test(metadata.version) && metadata.version !== '12.0.0' && metadata.version !== '12.0.1',
    'Native contributor assembly requires verified npm release line 12, version 12.0.2 or newer');
  return { path: cli, version: metadata.version, identity: fileIdentity(cli), packageIdentity: fileIdentity(packageFile) };
}

function registryFromInvocation() {
  const keys = Object.keys(process.env).filter((key) => key.toLowerCase() === 'npm_config_registry');
  demand(keys.length === 1 && process.env[keys[0]], 'Set an approved npm registry only in invocation environment (npm_config_registry); no caller/home npm configuration is inherited');
  const registry = new URL(process.env[keys[0]]);
  demand(registry.protocol === 'https:' && !registry.username && !registry.password && !registry.search && !registry.hash,
    'Build registry override must be an explicit credential-free HTTPS URL');
  return registry.href;
}

function validateRegistryLock(lock, registry) {
  const approved = new URL(registry);
  for (const [name, entry] of Object.entries(lock.packages)) {
    if (!name) continue;
    demand(!entry.link && typeof entry.version === 'string' && /^\d+\.\d+\.\d+(?:[-+][A-Za-z0-9.-]+)?$/.test(entry.version) &&
      typeof entry.integrity === 'string' && /^(?:sha1|sha256|sha384|sha512)-[A-Za-z0-9+/=]+$/.test(entry.integrity),
      `Dependency must have exact locked registry bytes; file/git/directory sources are not allowed: ${name}`);
    if (entry.resolved === undefined) continue;
    const url = new URL(entry.resolved);
    demand(url.protocol === 'https:' && !url.username && !url.password &&
      (url.hostname === 'registry.npmjs.org' || url.origin === approved.origin && url.pathname.startsWith(approved.pathname)),
    `Dependency lock contains an unapproved package feed/source: ${name}`);
  }
}

async function restoreDependencies(node, npm, directory, source, env, { production, target }) {
  const packageBefore = fileIdentity(path.join(directory, 'package.json'));
  const lockBefore = fileIdentity(path.join(directory, 'package-lock.json'));
  const [os, arch] = target.split('-');
  const dependencyEnv = { ...env, ...(production ? { npm_config_os: os, npm_config_cpu: arch, ...(os === 'linux' ? { npm_config_libc: 'glibc' } : {}) } : {}) };
  await runBuildCommand(node, [npm.path, 'ci', ...(production ? ['--omit=dev'] : []), '--ignore-scripts', '--no-bin-links',
    '--no-audit', '--no-fund', '--progress=false', '--loglevel=error',
    '--allow-directory=none', '--allow-file=none', '--allow-git=none', '--allow-remote=none'], {
    cwd: directory, env: dependencyEnv, timeout: 300_000, maxBuffer: 1024 * 1024, label: production ? 'Locked runtime dependency restoration' : 'Locked contributor compiler restoration'
  });
  demand(fileIdentity(path.join(directory, 'package.json')).sha256 === packageBefore.sha256 &&
    fileIdentity(path.join(directory, 'package-lock.json')).sha256 === lockBefore.sha256, 'npm ci changed selected source package/lock bytes');
  demand(fileIdentity(npm.path).sha256 === npm.identity.sha256, 'Build npm changed after identity admission');
  if (production) return verifyDependencyTree(directory, source.lock, target);
  return [];
}

function assertReleaseSource(projectRoot, sourceCommit, output) {
  demand(typeof sourceCommit === 'string' && /^[a-f0-9]{40}$/.test(sourceCommit), 'Release assembly requires an explicit immutable source commit');
  const git = findExternalExecutable('git', projectRoot);
  const execute = (args) => execFileSync(git, ['--no-pager', '-c', 'core.fsmonitor=false', ...args], {
    cwd: projectRoot, encoding: 'utf8', timeout: 15_000, maxBuffer: 1024 * 1024
  });
  demand(execute(['rev-parse', 'HEAD']).trim() === sourceCommit, 'Release source is not the exact selected commit');
  execute(['diff', '--no-ext-diff', '--quiet', 'HEAD', '--']);
  if (output) assertOwnedOutput(output);
  const outputPrefix = output ? `${path.relative(projectRoot, output.root).split(path.sep).join('/')}/` : undefined;
  const untracked = execute(['ls-files', '--others', '--exclude-standard', '-z']).split('\0').filter(Boolean);
  demand(untracked.every((file) => outputPrefix && file.startsWith(outputPrefix)), 'Release source has uncommitted/untracked inputs outside this exact owned build output');
}

async function releaseIdentity(projectRoot, sourceCommit) {
  assertReleaseSource(projectRoot, sourceCommit);
  const scope = JSON.parse(fs.readFileSync(confinedPath(projectRoot, 'assets/qualification/release-scope.json'), 'utf8'));
  demand(scope.candidate?.version === readSourceIdentity(projectRoot).pkg.version, 'Release source version is not the registered candidate');
  const signing = scope.verification?.nativeSigning;
  demand(signing && typeof signing.workflow === 'string', 'Release assembly requires registered native signing/provenance trust; development builds cannot invent release authority');
  validateWorkflowPolicy(scope.verification.workflows?.[signing.workflow], 'native-artifact', sourceCommit);
  demand(Object.keys(pinnedRuntime.targets).every((target) => typeof signing.identities?.[target] === 'string' && signing.identities[target].length > 0),
    'Release assembly requires explicit registered signer identities for all six targets');
}

async function canonicalReleaseMetadata(snapshot, target, runtime) {
  const module = await import(pathToFileURL(path.join(snapshot, 'dist/domain/distribution/index.js')).href);
  const floors = module.nativeTargetFloors[target.split('-')[0]];
  demand(floors, 'Target is absent from canonical native admission');
  if (target.startsWith('darwin-')) {
    const parts = String(floors.minimumHostVersion).split('.').map(Number);
    demand(parts[0] > 13 || parts[0] === 13 && parts[1] >= 5, 'Canonical macOS admission floor is weaker than the verified Node 24.20 macOS 13.5 binary; runtime owner must reconcile it');
  }
  if (target.startsWith('linux-')) {
    const parts = String(floors.minimumGlibc).split('.').map(Number);
    demand(parts[0] > 2 || parts[0] === 2 && parts[1] >= 28, 'Canonical glibc floor is weaker than the official pinned runtime');
    demand(module.compareNumericVersions(floors.minimumKernelVersion ?? runtime.upstream.minimumKernelVersion, runtime.upstream.minimumKernelVersion) >= 0,
      'Canonical kernel floor is weaker than the official pinned runtime');
  }
  return { nodeVersion: runtime.version, ...floors,
    ...(target.startsWith('linux-') ? { minimumKernelVersion: floors.minimumKernelVersion ?? runtime.upstream.minimumKernelVersion } : {}) };
}

async function verifyResources(bundle) {
  const adapter = await import(pathToFileURL(path.join(bundle, 'dist/adapters/packaged-assets/resource-catalog.js')).href);
  const result = adapter.verifyAllPackagedResourcesIntegrity();
  demand(result.valid === true && result.totalVerified > 0, `Packaged source resource integrity failed: ${result.errors.join('; ')}`);
  const catalog = adapter.loadPackagedTemplateCatalog(true);
  const profiles = adapter.loadPackagedProfilesCatalog(true);
  const resources = adapter.computeResourceInventorySummary(catalog);
  demand(resources.count === result.totalVerified, 'Native resource inventory does not match actual selected bytes');
  return { resources, resourcesDigest: catalog.digest, profilesDigest: profiles.digest };
}

async function inventoryRuntimeNotices(bundle, dependencies) {
  const noticeFile = (relative) => {
    const { sha256, size } = fileIdentity(path.join(bundle, relative), 2 * 1024 * 1024);
    return { path: relative, sha256, size };
  };
  const supplements = {
    '@cdktf/hcl2json@0.21.0': [
      { file: 'hcl2json-0.21.0-MPL-2.0.txt', url: 'https://raw.githubusercontent.com/hashicorp/terraform-cdk/v0.21.0/LICENSE',
        sha256: '8a318096d516c4b23566f94f4129260a9d4f72672dc52405573b619451f7b6c2' },
      { file: 'go-BSD-LICENSE.txt', url: 'https://raw.githubusercontent.com/golang/go/go1.27.1/LICENSE',
        sha256: '911f8f5782931320f5b8d1160a76365b83aea6447ee6c04fa6d5591467db9dad' }
    ]
  };
  const notices = [];
  for (const dependency of dependencies) {
    demand(typeof dependency.license === 'string' && dependency.license.length > 0, `Runtime dependency lacks redistribution license metadata: ${dependency.name}`);
    const root = path.join(bundle, dependency.path);
    const files = fs.readdirSync(root).filter((name) => /^(licen[cs]e|copying|notice)(\.|$)/i.test(name) && fs.lstatSync(path.join(root, name)).isFile())
      .map((name) => noticeFile(`${dependency.path}/${name}`));
    const registered = supplements[`${dependency.name}@${dependency.version}`];
    if (registered) {
      fs.mkdirSync(path.join(bundle, 'licenses'), { recursive: true, mode: 0o755 });
      for (const license of registered) {
        const destination = path.join(bundle, 'licenses', license.file);
        if (!fs.existsSync(destination)) await downloadPinnedFile(license.url, destination, license.sha256, 2 * 1024 * 1024);
        demand(fileIdentity(destination).sha256 === license.sha256, 'Supplemental runtime license bytes changed');
        files.push(noticeFile(`licenses/${license.file}`));
      }
    }
    demand(files.length > 0, `Runtime dependency omits license text and has no reviewed version-specific supplement: ${dependency.name}@${dependency.version}`);
    notices.push({ name: dependency.name, version: dependency.version, license: dependency.license, files,
      ...(registered ? { source: 'https://github.com/hashicorp/terraform-cdk/tree/v0.21.0/packages/@cdktf/hcl2json' } : {}) });
  }
  writeJson(path.join(bundle, 'THIRD_PARTY_NOTICES.json'), { schemaVersion: 1, dependencies: notices,
    nodeLicense: noticeFile('runtime/LICENSE') });
  return notices;
}

export async function createNativeLauncher(bundle, snapshot, target, work, env, projectRoot) {
  runtimeDefinition(target);
  const entrypoint = nativeEntrypoints(target).launcher;
  fs.mkdirSync(path.join(bundle, 'bin'), { mode: 0o755 });
  if (!target.startsWith('win32-')) {
    writeNew(path.join(bundle, entrypoint), posixLauncher(), 0o755);
    return { kind: 'posix-shell', entrypoint, sourceSha256: sha256(posixLauncher()) };
  }
  const go = findExternalExecutable('go', projectRoot);
  const goVersion = (await runBuildCommand(go, ['version'], { cwd: work, env, maxBuffer: 4096, timeout: 15_000, label: 'Existing Windows launcher compiler identity' })).trim();
  demand(/^go version go1\.(?:2[7-9]|[3-9]\d)\.\d+ /.test(goVersion), 'Windows bootstrap requires a verified existing Go 1.27+ compiler; no toolchain is bootstrapped');
  const goEnv = { ...env, GOOS: 'windows', GOARCH: target.endsWith('arm64') ? 'arm64' : 'amd64', CGO_ENABLED: '0',
    GOTOOLCHAIN: 'local', GOPROXY: 'off', GOSUMDB: 'off', GOENV: 'off', GOWORK: 'off', GO111MODULE: 'off',
    GOCACHE: path.join(work, 'go-cache'), GOPATH: path.join(work, 'go-path') };
  await runBuildCommand(go, ['build', '-trimpath', '-buildvcs=false', '-ldflags=-s -w -buildid=', '-o', path.join(bundle, entrypoint),
    path.join(snapshot, 'scripts/distribution/windows-launcher.go')], {
    cwd: work, env: goEnv, timeout: 180_000, label: 'Native Windows PE bootstrap compilation'
  });
  inspectNativeMachine(path.join(bundle, entrypoint), target);
  const goRoot = (await runBuildCommand(go, ['env', 'GOROOT'], { cwd: work, env: goEnv, timeout: 15_000, maxBuffer: 4096, label: 'Go license source identity' })).trim();
  demand(path.isAbsolute(goRoot), 'Go did not identify its actual installation root');
  let license = path.join(goRoot, 'LICENSE');
  if (!fs.existsSync(license) && path.basename(goRoot) === 'libexec' && go.startsWith(`${path.dirname(goRoot)}${path.sep}`)) {
    license = path.join(path.dirname(goRoot), 'LICENSE');
  }
  demand(fs.existsSync(license) && fileIdentity(license).size > 0, 'Missing Go runtime redistribution license in the verified compiler installation');
  fs.mkdirSync(path.join(bundle, 'licenses'), { recursive: true, mode: 0o755 });
  fs.copyFileSync(license, path.join(bundle, 'licenses/GO-LICENSE'), fs.constants.COPYFILE_EXCL);
  return { kind: 'windows-pe', entrypoint, compiler: goVersion, sourceSha256: fileIdentity(path.join(snapshot, 'scripts/distribution/windows-launcher.go')).sha256 };
}

export async function smokeNativeBundle(bundle, target, work, env, expectedRuntimeSha256) {
  demand(target === `${process.platform}-${process.arch}`, 'A cross-target archive cannot provide actual native-host execution evidence');
  demand(typeof expectedRuntimeSha256 === 'string' && /^[a-f0-9]{64}$/.test(expectedRuntimeSha256), 'Runtime probes require the independently verified official binary digest');
  const safePath = path.join(work, 'empty-path');
  if (!fs.existsSync(safePath)) fs.mkdirSync(safePath, { mode: 0o700 });
  demand(fs.readdirSync(safePath).length === 0, 'No-ambient-tool smoke PATH must be an empty owned directory');
  const probeEnv = { ...env, PATH: safePath, NODE_OPTIONS: '--require=untrusted-preload-must-not-run', NODE_PATH: '/untrusted-module-scope' };
  const launcher = path.join(bundle, nativeEntrypoints(target).launcher);
  const runtime = path.join(bundle, nativeEntrypoints(target).runtime);
  const documentation = verifyPackagedDocumentation(bundle, inventoryTree(bundle));
  const observations = [{ args: ['packaged-documentation', 'local-file-link-closure'], result: documentation }];
  for (const args of [['--version'], ['--help'], ['capabilities', '--json'], ['skills', 'list', '--json'], ...nativePlanSmokeCases]) {
    demand(fileIdentity(runtime).sha256 === expectedRuntimeSha256, 'Private runtime bytes changed before probe execution');
    const stdout = await runBuildCommand(launcher, args, { cwd: work, env: probeEnv, timeout: 30_000, maxBuffer: 1024 * 1024, label: `Private bundle ${args.join(' ')}` });
    if (args[0] === '--version') demand(stdout.trim() === `Liftoff ${JSON.parse(fs.readFileSync(path.join(bundle, 'package.json'), 'utf8')).version}`, 'Installed private CLI version differs from selected source');
    if (args.includes('--json')) JSON.parse(stdout);
    if (args[0] === 'plan') demand(stdout.includes('Artifacts (') && stdout.includes('liftoff.manifest.json') && stdout.includes('backend/'),
      'Public plan did not render the selected profile artifact/resource inventory');
    observations.push({ args, stdoutSha256: sha256(stdout), bytes: Buffer.byteLength(stdout) });
  }
  demand(fileIdentity(runtime).sha256 === expectedRuntimeSha256, 'Private runtime bytes changed before resource verification');
  const assets = await runBuildCommand(runtime, ['--input-type=module', '-e',
    'const m=await import(process.argv[1]);const r=m.verifyAllPackagedResourcesIntegrity();if(!r.valid||r.totalVerified===0)throw Error(JSON.stringify(r));console.log(JSON.stringify(r));',
    pathToFileURL(path.join(bundle, 'dist/adapters/packaged-assets/resource-catalog.js')).href], {
    cwd: work, env: { ...env, PATH: safePath }, timeout: 30_000, maxBuffer: 1024 * 1024, label: 'Private runtime complete packaged-resource verification'
  });
  observations.push({ args: ['private-runtime', 'verifyAllPackagedResourcesIntegrity'], result: JSON.parse(assets),
    stdoutSha256: sha256(assets), bytes: Buffer.byteLength(assets) });
  const stagingRoot = path.join(work, 'generation-staging');
  if (!fs.existsSync(stagingRoot)) fs.mkdirSync(stagingRoot, { mode: 0o700 });
  demand(fs.readdirSync(stagingRoot).length === 0, 'Generation smoke requires a new empty task-owned staging root');
  demand(fileIdentity(runtime).sha256 === expectedRuntimeSha256, 'Private runtime bytes changed before packaged generation');
  const generated = await runBuildCommand(runtime, ['--input-type=module', '-e', packagedGenerationSmoke,
    pathToFileURL(`${bundle}${path.sep}`).href], {
    cwd: work, env: { ...env, PATH: safePath, LIFTOFF_STAGING_ROOT: stagingRoot },
    timeout: 60_000, maxBuffer: 1024 * 1024, label: 'Private runtime packaged generation and manifest readback'
  });
  const generation = JSON.parse(generated);
  demand(generation.kind === 'packaged-generation-source-smoke' && generation.results.length === 2 &&
    generation.results.every((entry) => Number.isSafeInteger(entry.files) && entry.files > 0),
  'Packaged generator did not produce and read back both selected profile fixtures');
  demand(fs.readdirSync(stagingRoot).length === 0, 'Packaged generation left an unexpected staging workspace');
  observations.push({ args: ['private-runtime', 'buildArtifacts', 'writeStagedArtifacts', 'loadManifest'],
    result: generation, stdoutSha256: sha256(generated), bytes: Buffer.byteLength(generated) });
  return { kind: 'current-host-runtime-closure', target, ambientNodeOrNpmRequired: false, observations, nativeReleaseQualified: false };
}

export async function assembleNativeBundle(options) {
  demand(options && typeof options === 'object', 'Explicit native assembly options are required');
  const allowed = ['mode', 'target', 'projectRoot', 'outputDirectory', 'sourceCommit', 'nodeArchive', 'npmCli'];
  demand(Object.keys(options).every((key) => allowed.includes(key)), 'Unknown native build option: version/source/trust overrides and compatibility defaults are forbidden');
  demand(options.mode === 'development' || options.mode === 'release', 'Choose explicit development or release mode');
  const definition = runtimeDefinition(options.target);
  const projectRoot = regularRoot(options.projectRoot ?? process.cwd());
  demand(typeof options.outputDirectory === 'string' && options.outputDirectory.length > 0, 'A new explicit owned output directory is required');
  demand(options.mode === 'release' || options.sourceCommit === undefined, 'Development source is identified by actual content/tree bytes, not a supplied commit claim');
  if (options.mode === 'release') await releaseIdentity(projectRoot, options.sourceCommit);
  const selected = readSourceIdentity(projectRoot);
  const outputRelative = path.relative(projectRoot, path.resolve(projectRoot, options.outputDirectory)).split(path.sep).join('/');
  demand(outputRelative.startsWith('build/') && !selected.pkg.files.some((entry) => outputRelative === entry ||
    outputRelative.startsWith(`${entry}/`) || entry.startsWith(`${outputRelative}/`)), 'Build output must be a new build/ directory outside every selected source/shipping input');
  const registry = registryFromInvocation();
  validateRegistryLock(selected.lock, registry);
  const node = fs.realpathSync(process.execPath);
  demand(!path.relative(projectRoot, node).startsWith(`src${path.sep}`) && !node.startsWith(`${projectRoot}${path.sep}`), 'Build Node must be independently installed outside the project');
  demand(/^v(?:24|2[5-9]|[3-9]\d)\./.test(process.version) && (Number(process.versions.node.split('.')[0]) > 24 || Number(process.versions.node.split('.')[1]) >= 20), 'Build Node must be an actual supported stable 24.20+ runtime');
  const nodeIdentity = fileIdentity(node);
  inspectNativeMachine(node, `${process.platform}-${process.arch}`);
  const npm = npmCliIdentity(projectRoot, options.npmCli);
  const python = findExternalExecutable(process.platform === 'win32' ? 'python' : 'python3', projectRoot);
  let archivePath;
  if (options.nodeArchive !== undefined) {
    const relative = path.relative(projectRoot, path.resolve(projectRoot, options.nodeArchive)).split(path.sep).join('/');
    archivePath = confinedPath(projectRoot, relative);
  }
  const output = createOwnedOutput(projectRoot, options.outputDirectory);
  const work = path.join(output.root, '.work');
  const snapshot = path.join(work, 'source');
  fs.mkdirSync(snapshot, { recursive: true, mode: 0o700 });
  const workIdentity = fs.lstatSync(work);
  const env = cleanBuildEnvironment(work, { npm_config_registry: registry });
  const statusFile = path.join(output.root, 'build-status.json');
  writeJson(statusFile, { schemaVersion: 1, state: 'building', mode: options.mode, target: options.target, productionQualified: false });
  const statusIdentity = fs.lstatSync(statusFile);
  const updateStatus = (value) => {
    assertOwnedOutput(output);
    const stat = fs.lstatSync(statusFile);
    demand(stat.isFile() && !stat.isSymbolicLink() && stat.dev === statusIdentity.dev && stat.ino === statusIdentity.ino && stat.nlink === 1,
      'Build status identity changed; refusing to overwrite another file');
    const fd = fs.openSync(statusFile, fs.constants.O_WRONLY | (fs.constants.O_NOFOLLOW ?? 0));
    try {
      const opened = fs.fstatSync(fd);
      demand(opened.dev === statusIdentity.dev && opened.ino === statusIdentity.ino, 'Build status changed before update');
      fs.ftruncateSync(fd, 0);
      fs.writeFileSync(fd, `${JSON.stringify(value, null, 2)}\n`);
    } finally { fs.closeSync(fd); }
  };
  try {
    const npmVersion = (await runBuildCommand(node, [npm.path, '--version'], { cwd: work, env, timeout: 15_000, maxBuffer: 4096, label: 'Existing npm tool identity' })).trim();
    demand(npmVersion === npm.version, 'Observed npm version differs from its independently resolved package identity');
    const source = captureSource(projectRoot, snapshot);
    const cache = process.env.LIFTOFF_NPM_CACHE_SOURCE
      ? seedLockedPublicCache(source.lock, process.env.LIFTOFF_NPM_CACHE_SOURCE, path.join(work, 'npm-cache'))
      : { source: 'empty-private-cache', tarballs: 0, bytes: 0 };
    const head = (await runBuildCommand(findExternalExecutable('git', projectRoot), ['--no-pager', 'rev-parse', 'HEAD'], {
      cwd: projectRoot, env, timeout: 15_000, maxBuffer: 4096, label: 'Observed source HEAD'
    })).trim();
    const leaf = options.mode === 'release'
      ? `liftoff-v${source.pkg.version}-${options.target}`
      : `liftoff-development-${source.pkg.version}-${source.treeSha256.slice(0, 16)}-${options.target}`;
    const bundle = path.join(output.root, leaf);
    fs.mkdirSync(bundle, { mode: 0o755 });
    fs.mkdirSync(path.join(bundle, 'runtime'), { mode: 0o755 });
    const runtime = await preparePrivateRuntime({ target: options.target, runtimeDirectory: path.join(bundle, 'runtime'),
      workDirectory: work, archivePath, python, env });
    await restoreDependencies(node, npm, snapshot, source, env, { production: true, target: `${process.platform}-${process.arch}` });
    const tooling = path.join(work, 'compiler');
    fs.mkdirSync(tooling, { mode: 0o700 });
    const compilerSource = compilerLockSubset(source);
    writeJson(path.join(tooling, 'package.json'), compilerSource.pkg);
    writeJson(path.join(tooling, 'package-lock.json'), compilerSource.lock);
    await restoreDependencies(node, npm, tooling, compilerSource, env, { production: false, target: `${process.platform}-${process.arch}` });
    const compilerPackage = JSON.parse(fs.readFileSync(path.join(tooling, 'node_modules/typescript/package.json'), 'utf8'));
    demand(compilerPackage.name === 'typescript' && compilerPackage.version === source.lock.packages['node_modules/typescript']?.version, 'Private compiler differs from the selected source lock');
    const compiler = path.join(tooling, 'node_modules/typescript/bin/tsc');
    fileIdentity(compiler);
    await runBuildCommand(node, [compiler, '-p', path.join(snapshot, 'tsconfig.json'), '--typeRoots', path.join(tooling, 'node_modules/@types')], { cwd: snapshot, env, timeout: 180_000, label: 'Sealed-source TypeScript build' });
    const runtimeInputs = source.files.filter((file) => source.pkg.files.some((entry) => entry !== 'dist' && (file.path === entry || file.path.startsWith(`${entry}/`))) ||
      file.path === 'package.json' || file.path === 'package-lock.json');
    for (const file of runtimeInputs) copyInventoriedFile(snapshot, bundle, { ...file, mode: fileIdentity(path.join(snapshot, file.path)).mode });
    const compiled = inventoryTree(path.join(snapshot, 'dist'));
    demand(compiled.some((file) => file.path === 'cli.js'), 'Compilation did not produce the actual CLI entrypoint');
    for (const file of compiled) copyInventoriedFile(snapshot, bundle, { ...file, path: `dist/${file.path}` });
    const dependencies = await restoreDependencies(node, npm, bundle, source, env, { production: true, target: options.target });
    const npmInternalLock = path.join(bundle, 'node_modules/.package-lock.json');
    if (fs.existsSync(npmInternalLock)) fs.unlinkSync(npmInternalLock);
    const { resources, resourcesDigest, profilesDigest } = await verifyResources(bundle);
    const launcher = await createNativeLauncher(bundle, snapshot, options.target, work, env, projectRoot);
    const notices = await inventoryRuntimeNotices(bundle, dependencies);
    const builtAt = new Date().toISOString();
    const sourceIdentity = options.mode === 'release'
      ? { kind: 'reviewed-commit', commit: options.sourceCommit, treeSha256: source.treeSha256 }
      : { kind: 'unqualified-working-tree', observedHeadCommit: head, treeSha256: source.treeSha256, releaseCommit: null };
    if (options.mode === 'release') {
      const constraints = await canonicalReleaseMetadata(snapshot, options.target, runtime);
      writeJson(path.join(bundle, 'liftoff-build-manifest.json'), { schemaVersion: 1, product: 'liftoff', version: source.pkg.version,
        target: options.target, sourceCommit: options.sourceCommit, builtAt, runtime: constraints, resources });
      const infoReader = await import(pathToFileURL(path.join(bundle, 'dist/adapters/packaged-assets/build-info.js')).href);
      const buildInfo = infoReader.validateNativeBuildInfo(nativeBuildInfoDocument({
        version: source.pkg.version, sourceCommit: options.sourceCommit, target: options.target,
        nodeVersion: runtime.version, resourcesDigest, profilesDigest, builtAt
      }));
      writeJson(path.join(bundle, 'build-info.json'), buildInfo);
    } else {
      writeJson(path.join(bundle, 'development-build-manifest.json'), { schemaVersion: 1, kind: 'unqualified-development-bundle',
        product: 'liftoff', version: source.pkg.version, target: options.target, source: sourceIdentity, builtAt,
        runtime, resources, entrypoints: nativeEntrypoints(options.target), nativeReleaseQualified: false });
    }
    writeJson(path.join(bundle, 'runtime-dependencies.json'), { schemaVersion: 1, lockSha256: fileIdentity(path.join(bundle, 'package-lock.json')).sha256, packages: dependencies });
    makeReadOnly(bundle);
    const files = inventoryTree(bundle);
    const documentation = verifyPackagedDocumentation(bundle, files);
    const inventoryPath = path.join(output.root, 'payload-inventory.json');
    writeJson(inventoryPath, files);
    const probes = options.target === `${process.platform}-${process.arch}` ? await smokeNativeBundle(bundle, options.target, work, env, runtime.executable.sha256)
      : { kind: 'source-only-cross-target-construction', target: options.target, nativeReleaseQualified: false };
    demand(canonicalJson(inventoryTree(bundle)) === canonicalJson(files), 'Native CLI modified its read-only installed payload during closure checks');
    const archive = path.join(output.root, `${leaf}.${options.target.startsWith('win32-') ? 'zip' : 'tar.gz'}`);
    await runBuildCommand(python, [fileURLToPath(new URL('./native-build-archive.py', import.meta.url)), 'pack', bundle, inventoryPath, archive], {
      cwd: work, env, timeout: 180_000, maxBuffer: 4096, label: 'Inventoried native archive creation'
    });
    const archiveIdentity = fileIdentity(archive, 1024 * 1024 * 1024);
    const archiveFile = inspectFile(projectRoot, path.relative(projectRoot, archive).split(path.sep).join('/'), archiveIdentity.sha256);
    const archiveDocumentation = inspectArchiveDocumentation(archiveFile,
      options.target.startsWith('win32-') ? 'zip' : 'tar.gz', leaf, snapshot);
    demand(canonicalJson(archiveDocumentation) === canonicalJson(documentation), 'Archive documentation differs from the actual payload link closure');
    demand(fileIdentity(node).sha256 === nodeIdentity.sha256, 'Build Node changed during assembly');
    if (options.mode === 'release') assertReleaseSource(projectRoot, options.sourceCommit, output);
    assertOwnedOutput(output);
    const result = { schemaVersion: 1, state: 'assembled-unqualified', mode: options.mode, version: source.pkg.version,
      target: options.target, bundleDirectory: bundle, archivePath: archive, archive: archiveIdentity, source: sourceIdentity,
      sourceFiles: source.files, runtime, resources, entrypoints: nativeEntrypoints(options.target), launcher, probes,
      documentation, archiveDocumentation,
      runtimeLicensePackages: notices.length,
      tools: { node: { version: process.versions.node, sha256: nodeIdentity.sha256 }, npm: { version: npm.version, sha256: npm.identity.sha256 },
        typescript: { version: compilerPackage.version, lockSha256: sha256(canonicalJson(compilerSource.lock)) }, cache },
      productionQualified: false, signingState: 'unsigned-build-output' };
    updateStatus(result);
    const currentWork = fs.lstatSync(work);
    demand(currentWork.isDirectory() && !currentWork.isSymbolicLink() && currentWork.dev === workIdentity.dev && currentWork.ino === workIdentity.ino,
      'Build work directory changed identity; retaining it instead of cleanup');
    fs.rmSync(work, { recursive: true, force: false });
    return result;
  } catch (error) {
    assertOwnedOutput(output);
    updateStatus({ schemaVersion: 1, state: 'failed', mode: options.mode, target: options.target,
      error: error instanceof Error ? error.message : String(error), retainedWorkDirectory: work, productionQualified: false });
    throw new Error(`Native assembly failed; owned partial output retained at ${output.root}: ${error instanceof Error ? error.message : String(error)}`);
  }
}

export function parseNativeBuildArgs(args) {
  demand(args.length > 0 && args.length % 2 === 0, 'Usage: node scripts/distribution/assemble-native-bundle.mjs --mode development|release --target OS-ARCH --output NEW-PATH [--source-commit SHA] [--node-archive PATH] [--npm-cli ABSOLUTE-PATH]');
  const names = { '--mode': 'mode', '--target': 'target', '--output': 'outputDirectory', '--source-commit': 'sourceCommit', '--node-archive': 'nodeArchive', '--npm-cli': 'npmCli' };
  const options = {};
  for (let index = 0; index < args.length; index += 2) {
    demand(Object.hasOwn(names, args[index]) && !Object.hasOwn(options, names[args[index]]) && args[index + 1] && !args[index + 1].startsWith('--'), 'Unknown, duplicate or empty native build option');
    options[names[args[index]]] = args[index + 1];
  }
  return options;
}

if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  try {
    const result = await assembleNativeBundle(parseNativeBuildArgs(process.argv.slice(2)));
    process.stdout.write(`${result.state}: ${result.bundleDirectory}\nArchive: ${result.archivePath}\nSource tree SHA-256: ${result.source.treeSha256}\nNo native release qualification or publication was performed.\n`);
  } catch (error) {
    process.stderr.write(`${error instanceof Error ? error.message : String(error)}\n`);
    process.exitCode = 1;
  }
}
